export const PLAYER_BY_GSIS_ID = Object.fromEntries(
  NFL_PLAYERS.map(p => [p.gsis_id, p])
);
export const PLAYERS_BY_POSITION = NFL_PLAYERS.reduce((acc, p) => {
  if (!acc[p.position]) acc[p.position] = [];
  acc[p.position].push(p);
  return acc;
}, {});
